@pytest.mark.parametrize("case", CASES, ids=[c["id"] for c in CASES])
def test_importer_diagnostics_track_dependency_state(run, workdir, case):
    """CATCHES: an importer analysed against a stale dependency, a dependency error
    reported with different text or range, errors from two modules combined
    differently, or disk not winning again after the buffer closes."""
    S.check(run, workdir, case, __file__)
